import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"Performance policy","description":"","frontmatter":{},"headers":[],"relativePath":"benchmarks.md","filePath":"benchmarks.md","lastUpdated":1785223095000}`),a={name:`benchmarks.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="performance-policy" tabindex="-1">Performance policy <a class="header-anchor" href="#performance-policy" aria-label="Permalink to “Performance policy”">​</a></h1><p>Performance evidence is collected from optimized native bindings. Debug bindings are useful for development and correctness checks, but they are not a release-performance signal.</p><h2 id="release-gate" tabindex="-1">Release gate <a class="header-anchor" href="#release-gate" aria-label="Permalink to “Release gate”">​</a></h2><p><code>pnpm run bench:report</code> builds the native binding with Cargo&#39;s release profile, runs every Vitest benchmark three times, and writes the median report to <code>benchmarks/current.json</code>. The CI benchmark job pins Ubuntu 24.04, Node.js 24, and the repository Rust toolchain so that reports remain like-for-like at the software boundary.</p><p>The representative compatibility case runs the same Roboto input and <code>glyph + ttf2woff</code> request through fontmin-rs and classic Fontmin in each trial. Its paired mean-time ratio is release-blocking when fontmin-rs exceeds 1.10. Comparing both implementations in the same process makes this gate less sensitive to hosted-runner hardware variation than an absolute millisecond threshold.</p><p>The committed <a href="../benchmarks/baseline.json"><code>benchmarks/baseline.json</code></a> records the machine fingerprint, fixture checksum, three individual means, median metrics, and parity result. Re-record it only with:</p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bench:baseline</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Review the full diff before committing a new baseline. A slower result must be confirmed with three additional like-for-like runs and either fixed or documented as an intentional correctness tradeoff.</p><h2 id="current-result" tabindex="-1">Current result <a class="header-anchor" href="#current-result" aria-label="Permalink to “Current result”">​</a></h2><p>The release-profile baseline records the representative fontmin-rs pipeline at 0.1485 times the classic Fontmin mean, or roughly 6.73 times faster. The earlier debug-profile snapshot was not a product regression; replacing it with a release-profile gate resolves that measurement error.</p><p>Absolute timings for subset, WOFF, WOFF2, SVG, and the modern-web pipeline stay in the report for diagnosis. Hosted-runner absolute timings are evidence, not a hard gate, because CPU allocation can change between jobs.</p><p>For a coarse CPU profile of the representative pipeline, run <code>pnpm run bench:profile</code>. It executes 2,500 release-binding iterations and writes an ignored <code>.cpuprofile</code> under <code>benchmarks/</code>. The beta.3 profile confirms that glyph subsetting is the largest named block; JavaScript pipeline orchestration is not a material hotspot. Because the paired gate is already well above parity, beta.3 records no intentional correctness-for-performance tradeoff.</p>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};